-- Kiss New York: Shampoo Tonalizante Castanho Médio (Color Change, caixa com 3 unidades)
-- Preço de TESTE R$ 1,00 e ativo para venda (preço definitivo depois da reunião com o contador). Impostos em branco.
INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Kiss New York', true, 12, now(), now())
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "products" ("id", "sku", "name", "brandId", "description", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "internalNotes", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'KISS-TONALIZANTE-CAST-MED', 'Shampoo Tonalizante Castanho Médio Color Change (3 unidades)', b."id",
       'Color Change Shampoo • Cobertura dos fios grisalhos em 3 a 7 minutos • Sem amônia • Enriquecido com ginseng • Para todos os tipos de cabelo • Caixa com 3 unidades',
       'UN', 0, 0, 100, 0, 0, true,
       'PREÇO DE TESTE (R$ 1,00). Definir o preço real após a reunião com o contador.', now(), now()
  FROM "brands" b WHERE b."name" = 'Kiss New York'
ON CONFLICT ("sku") DO NOTHING;

INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'kiss-shampoo-tonalizante-castanho-medio.webp', 'image/webp', 50784, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'kiss-shampoo-tonalizante-castanho-medio.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'kiss-shampoo-tonalizante-castanho-medio.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'KISS-TONALIZANTE-CAST-MED' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
